const getAssignedWorkSummaryCounts = `-- name: GetAssignedWorkSummaryCounts :one
SELECT
  COUNT(*) FILTER (WHERE urgency_bucket = 'due_today')::int AS due_today_count,
  COUNT(*) FILTER (WHERE urgency_bucket = 'overdue')::int AS overdue_count
FROM (
  SELECT CASE
    WHEN t.due_date < $1::date THEN 'overdue'
    ELSE 'due_today'
  END AS urgency_bucket
  FROM collaboration.task t
  JOIN collaboration.task_assignee ta
    ON ta.organization_id = t.organization_id
   AND ta.task_id = t.id
  JOIN collaboration.project_state ps
    ON ps.organization_id = t.organization_id
   AND ps.id = t.state_id
  WHERE t.organization_id = $2
    AND ta.employee_id = $3
    AND ta.role = 'assignee'
    AND t.is_deleted = FALSE
    AND ps.is_closed = FALSE
    AND t.due_date IS NOT NULL
    AND t.due_date <= $1::date
    AND ($4::boolean OR t.task_kind <> 'ritual_instance')
) filtered
`

type GetAssignedWorkSummaryCountsParams struct {
	AsOfDate               pgtype.Date `json:"as_of_date"`
	OrganizationID         dbuuid.UUID `json:"organization_id"`
	EmployeeID             dbuuid.UUID `json:"employee_id"`
	IncludeRitualInstances bool        `json:"include_ritual_instances"`
}

type GetAssignedWorkSummaryCountsRow struct {
	DueTodayCount int32 `json:"due_today_count"`
	OverdueCount  int32 `json:"overdue_count"`
}

func (q *Queries) GetAssignedWorkSummaryCounts(ctx context.Context, db DBTX, arg *GetAssignedWorkSummaryCountsParams) (*GetAssignedWorkSummaryCountsRow, error) {
	row := db.QueryRow(ctx, getAssignedWorkSummaryCounts,
		arg.AsOfDate,
		arg.OrganizationID,
		arg.EmployeeID,
		arg.IncludeRitualInstances,
	)
	var i GetAssignedWorkSummaryCountsRow
	err := row.Scan(&i.DueTodayCount, &i.OverdueCount)
	return &i, err
}

